use std::io::Write;
use std::path::Path;

use callisto_model::{CommandError, CommandOutput, CommandRunner};

/// A `git` child that ignores the machine's global, system and command-line config, so a developer's `insteadOf`,
/// signing or hooks never reach a fixture; repository config and the caller's own environment still apply.
pub fn git_command() -> std::process::Command {
    let mut command = std::process::Command::new("git");
    command
        .env("GIT_CONFIG_GLOBAL", "/dev/null")
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env_remove("GIT_CONFIG_PARAMETERS")
        .env_remove("GIT_CONFIG_COUNT");
    command
}

/// A [`CommandRunner`] that runs the real `git`, for tests that read a
/// fixture repository through `callisto_model::vcs::GitAccess`. Every other program
/// succeeds with no output.
pub struct GitRunner;

impl CommandRunner for GitRunner {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
        self.run_with_env(program, args, cwd, &[])
    }

    fn run_with_env(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        env: &[(&str, &str)],
    ) -> Result<CommandOutput, CommandError> {
        if program != "git" {
            return Ok(CommandOutput {
                exit_code: Some(0),
                stdout: String::new(),
                stderr: String::new(),
            });
        }
        let output = git_command()
            .args(args)
            .current_dir(cwd)
            .envs(env.iter().copied())
            .output()
            .map_err(|e| CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            })?;
        Ok(CommandOutput {
            exit_code: output.status.code(),
            stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
            stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
        })
    }

    fn run_with_stdin(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        stdin: &[u8],
    ) -> Result<CommandOutput, CommandError> {
        if program != "git" {
            return Err(CommandError::Unsupported {
                program: program.to_string(),
                reason: "the fixture runner only pipes input to git".to_string(),
            });
        }
        let mut child = git_command()
            .args(args)
            .current_dir(cwd)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
