/// The deadline for purely local git reads (`rev-parse`, `for-each-ref`, `remote get-url`, `diff --cached`).
pub const LOCAL_GIT_TIMEOUT: Duration = Duration::from_secs(60);

/// Trait for executing subprocess commands.
pub trait CommandRunner: Send + Sync {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError>;

    /// Run a command with a hard wall-clock timeout. If the process does not
    /// exit before `timeout` elapses it is killed and
    /// [`CommandError::TimedOut`] is returned.
    ///
    /// The default implementation ignores `timeout` and delegates to [`Self::run`].
    /// Implementors that control a real subprocess should override this with an
    /// actual deadline check.
    fn run_with_timeout(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        _timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        self.run(program, args, cwd)
    }

    /// Run a child after removing selected inherited environment variables.
    /// The default fails closed: runners that spawn real subprocesses must implement filtering explicitly.
    fn run_with_timeout_env_filtered(
        &self,
        program: &str,
        _args: &[&str],
        _cwd: &Path,
        _timeout: Duration,
        removed: &[&str],
    ) -> Result<CommandOutput, CommandError> {
        if removed.is_empty() {
            return self.run_with_timeout(program, _args, _cwd, _timeout);
        }
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this command runner does not support filtering the child environment".to_string(),
        })
    }

    /// Run a child with extra environment variables, such as `GIT_INDEX_FILE` for a git command on a temporary index.
    /// Runners without an explicit child-environment implementation fail closed.
    fn run_with_env(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        env: &[(&str, &str)],
    ) -> Result<CommandOutput, CommandError> {
        if env.is_empty() {
            return self.run(program, args, cwd);
        }
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this command runner does not support a child environment".to_string(),
        })
    }

    /// Run a publisher with credentials supplied only to that child.
    /// Runners without an explicit child-environment implementation fail closed.
    fn run_with_timeout_publisher(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
        env: &[(&str, &str)],
    ) -> Result<CommandOutput, CommandError> {
        if env.is_empty() {
            return self.run_with_timeout(program, args, cwd, timeout);
        }
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this command runner does not support a publisher child environment".to_string(),
        })
    }

    /// Like [`Self::run_with_timeout`], but for an internal existence/probe
    /// check whose stderr looks like a failure on the common path (e.g.
