/// Makes every `git` that `command` or its descendants start ignore global, system and command-line config.
pub fn ignore_machine_git_config(command: &mut std::process::Command) -> &mut std::process::Command {
    command
        .env("GIT_CONFIG_GLOBAL", "/dev/null")
        .env("GIT_CONFIG_NOSYSTEM", "1")
        .env_remove("GIT_CONFIG_PARAMETERS")
        .env_remove("GIT_CONFIG_COUNT")
}

